 WHERE slug = 'gemini' AND lang = 'en';

UPDATE tools SET cons = ARRAY[$x$Model and subscription naming (Flash, Pro, Argon, Plus, Ultra) is confusing$x$, $x$Gemini 4 Argon is not included on the Free or Plus tiers, only Pro and Ultra$x$, $x$Top-end Ultra plans cost $99.99 to $199.99 per month$x$, $x$No free API tier for Argon, and token pricing rises after November 30, 2026$x$, $x$AI Pro subscribers need a separate paid API key to use Argon in AI Studio or Antigravity$x$]::text[]
 WHERE slug = 'gemini' AND lang = 'en';

UPDATE tools SET choose_if = $x$["You live in Gmail, Docs and Google Workspace and want AI built in", "You want strong chat plus native image generation in one tool", "You are a developer wanting pay-per-token access to Google's flagship model", "You want a free assistant before committing to a paid plan", "You need AI Mode in Search alongside a Pro or Ultra subscription"]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "Is Gemini better than ChatGPT?", "a": "On Google Workspace tasks, Gemini's deep integration with Gmail, Docs and Sheets makes it the more convenient choice. General capability comparisons with other assistants shift too often to declare a lasting winner. Gemini is the strongest fit for people already inside Google's ecosystem, while other assistants may appeal more for general use depending on their own feature sets."}, {"q": "Is Gemini free?", "a": "There is a free plan, but it runs the Flash-Lite model only. Paid plans unlock more: Google AI Plus is $4.99/month with the Flash model, Google AI Pro is $19.99/month and includes the flagship Gemini 4 Argon model, and Google AI Ultra is $99.99/month or $199.99/month for higher usage limits."}, {"q": "Can Gemini generate images?", "a": "Yes. Gemini includes native image generation through the Nano Banana 2.1 model, released October 2026, alongside its chat and coding capabilities."}, {"q": "What is the difference between Gemini and Google Bard?", "a": "Bard was Google's original AI chatbot, rebranded as Gemini in February 2024. They are the same product — if you used Bard, you're now using Gemini. The rebrand accompanied a significant upgrade in model capabilities."}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'en';

