UPDATE tools SET faq = $x$[{"q": "Ist Gemini besser als ChatGPT?", "a": "Bei Aufgaben in Google Workspace macht die tiefe Integration mit Gmail, Docs und Sheets Gemini zur komfortableren Wahl. Allgemeine Leistungsvergleiche mit anderen Assistenten verändern sich zu häufig, um einen dauerhaften Gewinner zu benennen. Gemini passt am besten zu Menschen, die bereits in Googles Ökosystem arbeiten, während andere Assistenten je nach ihren eigenen Funktionen für allgemeine Nutzung attraktiver sein können."}, {"q": "Ist Gemini kostenlos?", "a": "Es gibt einen kostenlosen Plan, der jedoch nur das Flash-Lite-Modell nutzt. Bezahlte Pläne bieten mehr: Google AI Plus kostet 4,99 $/Monat mit dem Flash-Modell, Google AI Pro kostet 19,99 $/Monat und enthält das Flaggschiffmodell Gemini 4 Argon, und Google AI Ultra kostet 99,99 $/Monat oder 199,99 $/Monat für höhere Nutzungslimits."}, {"q": "Kann Gemini Bilder generieren?", "a": "Ja. Gemini bietet native Bildgenerierung über das im Oktober 2026 veröffentlichte Modell Nano Banana 2.1, zusätzlich zu seinen Chat- und Programmierfunktionen."}, {"q": "Was ist der Unterschied zwischen Gemini und Google Bard?", "a": "Bard war Googles ursprünglicher KI-Chatbot, der im Februar 2024 in Gemini umbenannt wurde. Es handelt sich um dasselbe Produkt — wer Bard genutzt hat, verwendet jetzt Gemini. Die Umbenennung ging mit einer deutlichen Verbesserung der Modellfähigkeiten einher."}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'de';

