UPDATE tools SET faq = $x$[{"q": "Gemini лучше, чем ChatGPT?", "a": "В задачах, связанных с Google Workspace, глубокая интеграция Gemini с Gmail, Docs и Sheets делает его более удобным выбором. Сравнения общих возможностей с другими ассистентами меняются слишком часто, чтобы объявить постоянного победителя. Gemini лучше всего подходит людям, уже находящимся внутри экосистемы Google, в то время как другие ассистенты могут быть привлекательнее для общего использования в зависимости от их собственных функций."}, {"q": "Gemini бесплатен?", "a": "Есть бесплатный план, но он работает только с моделью Flash-Lite. Платные тарифы открывают больше возможностей: Google AI Plus стоит $4.99 в месяц с моделью Flash, Google AI Pro стоит $19.99 в месяц и включает флагманскую модель Gemini 4 Argon, а Google AI Ultra стоит $99.99 или $199.99 в месяц за более высокие лимиты использования."}, {"q": "Может ли Gemini генерировать изображения?", "a": "Да. Gemini включает встроенную генерацию изображений через модель Nano Banana 2.1, выпущенную в октябре 2026 года, наряду с возможностями чата и программирования."}, {"q": "В чём разница между Gemini и Google Bard?", "a": "Bard был первоначальным чат-ботом Google на базе ИИ, переименованным в Gemini в феврале 2024 года. Это один и тот же продукт — если вы пользовались Bard, теперь вы пользуетесь Gemini. Ребрендинг сопровождался значительным улучшением возможностей моделей."}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'ru';

