UPDATE tools SET faq = $x$[{"q": "האם Gemini טוב יותר מ-ChatGPT?", "a": "במשימות Google Workspace, השילוב העמוק של Gemini עם Gmail, Docs ו-Sheets הופך אותו לבחירה הנוחה יותר. השוואות יכולת כלליות עם עוזרים אחרים משתנות לעיתים קרובות מכדי להכריז על מנצח קבוע. Gemini מתאים ביותר לאנשים שכבר נמצאים בתוך מערכת ה-Google, בעוד שעוזרים אחרים עשויים למשוך יותר לשימוש כללי, בהתאם ליכולות שלהם."}, {"q": "האם Gemini חינמי?", "a": "קיימת תוכנית חינמית, אך היא מריצה רק את דגם ה-Flash-Lite. תוכניות בתשלום פותחות יותר: Google AI Plus ב-$4.99 לחודש עם דגם ה-Flash, Google AI Pro ב-$19.99 לחודש הכולל את דגם הדגל Gemini 4 Argon, ו-Google AI Ultra ב-$99.99 לחודש או $199.99 לחודש עבור מגבלות שימוש גבוהות יותר."}, {"q": "האם Gemini יכול ליצור תמונות?", "a": "כן. Gemini כולל יצירת תמונות מובנית באמצעות דגם Nano Banana 2.1, שיצא באוקטובר 2026, לצד יכולות הצ'אט וכתיבת הקוד שלו."}, {"q": "מה ההבדל בין Gemini ל-Google Bard?", "a": "Bard היה הצ'אטבוט המקורי של Google המבוסס על בינה מלאכותית, ועבר מיתוג מחדש ל-Gemini בפברואר 2024. מדובר באותו מוצר — אם השתמשתם ב-Bard, אתם כעת משתמשים ב-Gemini. המיתוג מחדש לווה בשדרוג משמעותי ביכולות הדגם."}]$x$::jsonb
