UPDATE tools SET faq = $x$[{"q": "Gemini est-il meilleur que ChatGPT ?", "a": "Pour les tâches liées à Google Workspace, l'intégration poussée de Gemini avec Gmail, Docs et Sheets en fait le choix le plus pratique. Les comparaisons générales de capacités avec d'autres assistants évoluent trop souvent pour désigner un gagnant durable. Gemini convient le mieux aux personnes déjà intégrées à l'écosystème Google, tandis que d'autres assistants peuvent séduire davantage pour un usage général selon leurs propres fonctionnalités."}, {"q": "Gemini est-il gratuit ?", "a": "Il existe une formule gratuite, mais elle ne fait tourner que le modèle Flash-Lite. Les formules payantes débloquent davantage : Google AI Plus à 4,99 $/mois avec le modèle Flash, Google AI Pro à 19,99 $/mois qui inclut le modèle phare Gemini 4 Argon, et Google AI Ultra à 99,99 $/mois ou 199,99 $/mois pour des limites d'usage plus élevées."}, {"q": "Gemini peut-il générer des images ?", "a": "Oui. Gemini inclut la génération d'images native via le modèle Nano Banana 2.1, sorti en octobre 2026, en complément de ses capacités de chat et de codage."}, {"q": "Quelle est la différence entre Gemini et Google Bard ?", "a": "Bard était le chatbot IA original de Google, rebaptisé Gemini en février 2024. Il s'agit du même produit : si vous utilisiez Bard, vous utilisez désormais Gemini. Ce changement de nom s'est accompagné d'une amélioration significative des capacités du modèle."}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'fr';

