UPDATE tools SET faq = $x$[{"q": "O Gemini é melhor que o ChatGPT?", "a": "Em tarefas do Google Workspace, a integração profunda do Gemini com Gmail, Docs e Sheets o torna a opção mais conveniente. Comparações gerais de capacidade com outros assistentes mudam com muita frequência para declarar um vencedor duradouro. O Gemini é a opção mais adequada para quem já está inserido no ecossistema do Google, enquanto outros assistentes podem atrair mais para uso geral, dependendo de seus próprios recursos."}, {"q": "O Gemini é gratuito?", "a": "Existe um plano gratuito, mas ele executa apenas o modelo Flash-Lite. Os planos pagos desbloqueiam mais recursos: o Google AI Plus custa $4,99/mês com o modelo Flash, o Google AI Pro custa $19,99/mês e inclui o modelo principal Gemini 4 Argon, e o Google AI Ultra custa $99,99/mês ou $199,99/mês para limites de uso mais altos."}, {"q": "O Gemini consegue gerar imagens?", "a": "Sim. O Gemini inclui geração nativa de imagens por meio do modelo Nano Banana 2.1, lançado em outubro de 2026, além de suas capacidades de chat e programação."}, {"q": "Qual é a diferença entre o Gemini e o Google Bard?", "a": "O Bard era o chatbot de IA original do Google, renomeado como Gemini em fevereiro de 2024. São o mesmo produto — se você usava o Bard, agora está usando o Gemini. A mudança de nome veio acompanhada de uma melhoria significativa nas capacidades do modelo."}]$x$::jsonb
 WHERE slug = 'gemini' AND lang = 'pt';

