UPDATE tools SET faq = $x$[{"q": "Ist Claude besser als ChatGPT?", "a": "Das hängt von der Aufgabe ab. Claude liefert in der Regel starke Langform-Texte und kann sehr lange Dokumente dank seines Kontextfensters von 1 Million Tokens präzise verarbeiten. ChatGPT bietet mehr Funktionen (Bildgenerierung, Sprache, Plugins) und ein größeres App-Ökosystem. Die Programmierfähigkeiten variieren je nach Modell und Aufgabe, daher lohnt es sich, beide für den jeweiligen Arbeitsablauf zu testen."}, {"q": "Was ist kostenlos — ChatGPT oder Claude?", "a": "Beide bieten kostenlose Pläne an. Claudes kostenloser Plan bietet kostenfreien Zugang zu den Sonnet- und Haiku-Modellen, mit rollierend zurückgesetzten Nutzungsobergrenzen. ChatGPT bietet ebenfalls eine kostenlose Stufe mit eigenen Nutzungslimits. Claudes kostenpflichtiger Einstiegspunkt ist der Pro-Plan für 20 $/Monat bei monatlicher Abrechnung, oder 17 $/Monat bei jährlicher Abrechnung."}, {"q": "Welche KI ist besser zum Programmieren — ChatGPT oder Claude?", "a": "Beide sind starke Optionen. Claude Opus 5.5 ist für komplexes agentisches Programmieren konzipiert, wobei alle aktuellen Claude-Modelle ein Kontextfenster von 1 Million Tokens bieten, das bei großen Codebasen hilft. ChatGPT mit Code Interpreter glänzt bei Datenanalyse und dem Ausführen von Code. Was besser ist, hängt von der konkreten Programmieraufgabe und dem Arbeitsablauf ab."}]$x$::jsonb
 WHERE slug = 'claude' AND lang = 'de';

