 WHERE slug = 'meta-ai' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "What is Meta AI?", "a": "Meta AI is Meta's assistant built into WhatsApp, Instagram, Facebook, Messenger and Threads, plus Meta's AI glasses. It runs on Muse Spark, Meta Superintelligence Labs' proprietary model family. It can answer questions, draft and rewrite text, summarize threads, and help in group chats, all without leaving Meta's apps. It is free to use for everyday chat, alongside optional paid Meta One plans."}, {"q": "Is Meta AI free?", "a": "Yes, Meta AI chat itself is free inside Meta's apps. On September 15, 2026, Meta launched Meta One, a subscription system for extra image and video generation. It includes individual bundles, Core at $7.99 per month and Premium at $19.99 per month, and single-app plans: Instagram Plus and Facebook Plus at $3.99 per month each, and WhatsApp Plus at $2.99 per month."}, {"q": "Is Meta AI as good as ChatGPT?", "a": "Meta AI runs on Muse Spark, Meta Superintelligence Labs' proprietary model family, built for everyday conversation, drafting and summarizing directly inside Meta's apps, which makes it convenient if you already live in WhatsApp, Instagram or Messenger. There's no official benchmark comparison to OpenAI's ChatGPT in Meta's own materials, so it's best evaluated on convenience and integration rather than raw model performance."}, {"q": "What is Muse?", "a": "Muse is a separate personal AI agent app that Meta launched in September 2026, powered by the Muse Spark model family. It is available at muse.ai and through WhatsApp, currently rolling out in the US. It has its own free tier plus paid Power ($20/mo) and Maximum ($100/mo) plans, and is distinct from the Meta AI assistant built into Meta's main apps."}]$x$::jsonb
 WHERE slug = 'meta-ai' AND lang = 'en';

