UPDATE tools SET faq = $x$[{"q": "מהו Meta AI?", "a": "Meta AI הוא העוזר של Meta המוטמע ב-WhatsApp, Instagram, Facebook, Messenger ו-Threads, וכן במשקפי ה-AI של Meta. הוא פועל על Muse Spark, משפחת המודלים הקניינית של Meta Superintelligence Labs. הוא יכול לענות על שאלות, לנסח ולשכתב טקסט, לסכם שרשורי הודעות, ולעזור בצ'אטים קבוצתיים, הכול מבלי לצאת מאפליקציות Meta. הוא חינמי לשימוש בצ'אט יומיומי, לצד תוכניות Meta One בתשלום כאופציה."}, {"q": "האם Meta AI חינמי?", "a": "כן, הצ'אט של Meta AI עצמו חינמי בתוך אפליקציות Meta. ב-15 בספטמבר 2026, Meta השיקה את Meta One, מערכת מנויים ליצירת תמונות ווידאו נוספת. היא כוללת חבילות אישיות, Core ב-7.99 דולר לחודש ו-Premium ב-19.99 דולר לחודש, ותוכניות לאפליקציה בודדת: Instagram Plus ו-Facebook Plus ב-3.99 דולר לחודש כל אחת, ו-WhatsApp Plus ב-2.99 דולר לחודש."}, {"q": "האם Meta AI טוב כמו ChatGPT?", "a": "Meta AI פועל על Muse Spark, משפחת המודלים הקניינית של Meta Superintelligence Labs, שנבנתה לשיחה יומיומית, ניסוח וסיכום ישירות בתוך אפליקציות Meta, מה שהופך אותו לנוח אם אתם כבר חיים בתוך WhatsApp, Instagram או Messenger. אין השוואת מדדים רשמית מול ChatGPT של OpenAI בחומרים הרשמיים של Meta, ולכן עדיף להעריך אותו לפי נוחות ואינטגרציה ולא לפי ביצועי המודל הגולמיים."}, {"q": "מהו Muse?", "a": "Muse היא אפליקציית סוכן AI אישי נפרדת ש-Meta השיקה בספטמבר 2026, המופעלת על ידי משפחת המודלים Muse Spark. היא זמינה בכתובת muse.ai ודרך WhatsApp, ונמצאת כרגע בהשקה בארה״ב. יש לה שכבת חינם משלה, בנוסף לתוכניות בתשלום Power (20 דולר לחודש) ו-Maximum (100 דולר לחודש), והיא נפרדת מהעוזר Meta AI המוטמע באפליקציות הראשיות של Meta."}]$x$::jsonb
 WHERE slug = 'meta-ai' AND lang = 'he';

