UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Meta AI ?", "a": "Meta AI est l'assistant de Meta intégré à WhatsApp, Instagram, Facebook, Messenger et Threads, ainsi qu'aux lunettes IA de Meta. Il fonctionne sur Muse Spark, la famille de modèles propriétaire de Meta Superintelligence Labs. Il peut répondre aux questions, rédiger et reformuler des textes, résumer des fils de discussion, et aider dans les discussions de groupe, sans quitter les applications de Meta. Il est gratuit pour un usage courant, en complément de forfaits payants optionnels Meta One."}, {"q": "Meta AI est-il gratuit ?", "a": "Oui, le chat Meta AI en lui-même est gratuit dans les applications de Meta. Le 15 septembre 2026, Meta a lancé Meta One, un système d'abonnement pour la génération supplémentaire d'images et de vidéos. Il comprend des forfaits individuels, Core à 7,99 $ par mois et Premium à 19,99 $ par mois, ainsi que des forfaits mono-application : Instagram Plus et Facebook Plus à 3,99 $ par mois chacun, et WhatsApp Plus à 2,99 $ par mois."}, {"q": "Meta AI est-il aussi performant que ChatGPT ?", "a": "Meta AI fonctionne sur Muse Spark, la famille de modèles propriétaire de Meta Superintelligence Labs, conçue pour la conversation quotidienne, la rédaction et le résumé directement au sein des applications de Meta, ce qui le rend pratique si vous vivez déjà dans WhatsApp, Instagram ou Messenger. Il n'existe pas de comparaison officielle de performances avec ChatGPT d'OpenAI dans les documents de Meta, il vaut donc mieux l'évaluer sur la commodité et l'intégration plutôt que sur la performance brute du modèle."}, {"q": "Qu'est-ce que Muse ?", "a": "Muse est une application distincte d'agent IA personnel que Meta a lancée en septembre 2026, reposant sur la famille de modèles Muse Spark. Elle est disponible sur muse.ai et via WhatsApp, actuellement déployée aux États-Unis. Elle possède son propre niveau gratuit ainsi que des forfaits payants Power (20 $/mois) et Maximum (100 $/mois), et se distingue de l'assistant Meta AI intégré aux applications principales de Meta."}]$x$::jsonb
 WHERE slug = 'meta-ai' AND lang = 'fr';

