 WHERE slug = 'cursor' AND lang = 'en';

UPDATE tools SET cons = ARRAY[$x$Third-party models such as Claude or GPT are billed separately at API price from prepaid credit, on top of any subscription tier$x$, $x$Switching from an older standalone Cursor plan to The X Subscription cannot be undone$x$, $x$Grok and Cursor now share one weekly usage pool, which can run out faster for heavy users$x$, $x$As a VS Code fork it can trail upstream on some extensions and updates$x$, $x$Agentic edits require trust and review; sweeping changes can introduce subtle bugs$x$]::text[]
 WHERE slug = 'cursor' AND lang = 'en';

