 WHERE slug = 'cursor' AND lang = 'en';

UPDATE tools SET faq = $x$[{"q": "What is Cursor?", "a": "Cursor is an AI-native IDE based on VS Code. It gives AI full context of your codebase and can edit multiple files, run terminal commands, and complete tasks end-to-end as an agent."}, {"q": "How much does Cursor cost?", "a": "New customers sign up through The X Subscription, which has five tiers: Free, Plus at $8 per month, Premium at $30 per month, Super at $100 per month, and Ultra at $200 per month. These tiers share a weekly usage pool between Grok and Cursor. Third-party models such as Claude or GPT are not included in any tier and are billed separately at API list prices from prepaid credit. Customers who already had an older Cursor plan can keep it, but switching to The X Subscription is optional and cannot be reversed."}, {"q": "Is Cursor safe to use with my codebase?", "a": "The current description doesn't detail specific privacy or compliance features, but Cursor does offer an Enterprise tier with custom terms, which is typically where stricter data controls and team-level governance would be handled."}, {"q": "What models does Cursor use?", "a": "Cursor's bundled model is Grok, from xAI, included in every tier of The X Subscription and sharing a weekly usage pool with Cursor. Cursor also supports third-party models from vendors such as OpenAI, Anthropic, and Google, billed separately at API price from prepaid credit, and you can switch models per request in settings."}]$x$::jsonb
 WHERE slug = 'cursor' AND lang = 'en';

