UPDATE tools SET faq = $x$[{"q": "מה זה Cursor?", "a": "Cursor הוא IDE מבוסס AI המבוסס על VS Code. הוא מעניק ל-AI הקשר מלא של בסיס הקוד שלך ויכול לערוך מספר קבצים, להריץ פקודות טרמינל, ולהשלים משימות מקצה לקצה כסוכן."}, {"q": "כמה עולה Cursor?", "a": "לקוחות חדשים נרשמים דרך The X Subscription, שכוללת חמש רמות: Free, Plus תמורת 8$ לחודש, Premium תמורת 30$ לחודש, Super תמורת 100$ לחודש, ו-Ultra תמורת 200$ לחודש. רמות אלו חולקות מאגר שימוש שבועי בין Grok ל-Cursor. מודלים חיצוניים כגון Claude או GPT אינם כלולים באף רמה ומחויבים בנפרד לפי מחירי רשימת ה-API מתוך יתרת זיכוי מראש. לקוחות שכבר היו בתוכנית Cursor ישנה יכולים לשמור עליה, אך המעבר ל-The X Subscription הוא אופציונלי ולא ניתן לביטול."}, {"q": "האם בטוח להשתמש ב-Cursor עם בסיס הקוד שלי?", "a": "התיאור הנוכחי אינו מפרט תכונות פרטיות או תאימות ספציפיות, אך Cursor אכן מציע רמת Enterprise עם תנאים מותאמים אישית, שם בדרך כלל מטופלים בקרות נתונים מחמירות יותר וממשל ברמת הצוות."}, {"q": "באילו מודלים משתמש Cursor?", "a": "המודל המאוגד של Cursor הוא Grok, מבית xAI, הכלול בכל רמה של The X Subscription וחולק מאגר שימוש שבועי עם Cursor. Cursor תומך גם במודלים חיצוניים מספקים כגון OpenAI, Anthropic ו-Google, המחויבים בנפרד לפי מחיר ה-API מתוך יתרת זיכוי מראש, וניתן להחליף מודלים לפי בקשה בהגדרות."}]$x$::jsonb
 WHERE slug = 'cursor' AND lang = 'he';

