UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Cursor ?", "a": "Cursor est un IDE natif pour l'IA basé sur VS Code. Il donne à l'IA un contexte complet de votre base de code et peut modifier plusieurs fichiers, exécuter des commandes terminal et accomplir des tâches de bout en bout en tant qu'agent."}, {"q": "Combien coûte Cursor ?", "a": "Les nouveaux clients s'inscrivent via The X Subscription, qui comporte cinq niveaux : Free, Plus à 8 $ par mois, Premium à 30 $ par mois, Super à 100 $ par mois et Ultra à 200 $ par mois. Ces niveaux partagent un pool d'utilisation hebdomadaire entre Grok et Cursor. Les modèles tiers comme Claude ou GPT ne sont inclus dans aucun niveau et sont facturés séparément aux prix catalogue de l'API à partir d'un crédit prépayé. Les clients ayant déjà un ancien plan Cursor peuvent le conserver, mais le passage à The X Subscription est optionnel et irréversible."}, {"q": "Cursor est-il sûr à utiliser avec ma base de code ?", "a": "La description actuelle ne détaille pas de fonctionnalités spécifiques de confidentialité ou de conformité, mais Cursor propose un niveau Enterprise avec des conditions personnalisées, qui est généralement l'endroit où sont gérés les contrôles de données plus stricts et la gouvernance au niveau de l'équipe."}, {"q": "Quels modèles Cursor utilise-t-il ?", "a": "Le modèle intégré de Cursor est Grok, de xAI, inclus dans chaque niveau de The X Subscription et partageant un pool d'utilisation hebdomadaire avec Cursor. Cursor prend également en charge des modèles tiers de fournisseurs comme OpenAI, Anthropic et Google, facturés séparément au prix de l'API à partir d'un crédit prépayé, et vous pouvez changer de modèle par requête dans les paramètres."}]$x$::jsonb
 WHERE slug = 'cursor' AND lang = 'fr';

