UPDATE tools SET faq = $x$[{"q": "O que é o Cursor?", "a": "Cursor é um IDE nativo de IA baseado no VS Code. Ele dá à IA contexto completo da sua base de código e pode editar múltiplos arquivos, executar comandos de terminal e concluir tarefas de ponta a ponta como um agente."}, {"q": "Quanto custa o Cursor?", "a": "Novos clientes se inscrevem através do The X Subscription, que possui cinco níveis: Free, Plus por $8 por mês, Premium por $30 por mês, Super por $100 por mês e Ultra por $200 por mês. Esses níveis compartilham um conjunto de uso semanal entre o Grok e o Cursor. Modelos de terceiros, como Claude ou GPT, não estão incluídos em nenhum nível e são cobrados separadamente aos preços de tabela da API a partir de crédito pré-pago. Clientes que já tinham um plano antigo do Cursor podem mantê-lo, mas a mudança para o The X Subscription é opcional e não pode ser revertida."}, {"q": "É seguro usar o Cursor com minha base de código?", "a": "A descrição atual não detalha recursos específicos de privacidade ou conformidade, mas o Cursor oferece um nível Enterprise com termos personalizados, que normalmente é onde controles de dados mais rígidos e governança em nível de equipe seriam tratados."}, {"q": "Quais modelos o Cursor usa?", "a": "O modelo incluído no pacote do Cursor é o Grok, da xAI, presente em todos os níveis do The X Subscription e compartilhando um conjunto de uso semanal com o Cursor. O Cursor também suporta modelos de terceiros de fornecedores como OpenAI, Anthropic e Google, cobrados separadamente ao preço de API a partir de crédito pré-pago, e você pode trocar de modelo por solicitação nas configurações."}]$x$::jsonb
 WHERE slug = 'cursor' AND lang = 'pt';

