UPDATE tools SET faq = $x$[{"q": "Що таке Grok AI?", "a": "Grok — це AI-асистент від xAI, вбудований в X (Twitter), а також доступний як окремий продукт на grok.com. Він має доступ до публікацій X та трендових тем у реальному часі. Поточна флагманська модель — Grok 4.7, яка має контекстне вікно на 500 тисяч токенів і дату зрізу знань у травні 2026 року."}, {"q": "Чи Grok безкоштовний?", "a": "Так. З 12 жовтня 2026 року Grok включено в The X Subscription — пакет, який також охоплює Cursor та X Premium. Пакет має п'ять рівнів: Free, Plus за $8/міс, Premium за $30/міс, Super за $100/міс та Ultra за $200/міс, усі з щомісячною оплатою."}, {"q": "Чи Grok кращий за ChatGPT?", "a": "Незалежно перевіреного порівняння бенчмарків немає. Головні відмінності Grok — це доступ до публікацій X/Twitter у реальному часі, більш відвертий та упереджений стиль спілкування, а також багаторівневе ціноутворення API для розробників."}, {"q": "Чи генерує Grok зображення?", "a": "Так, Grok включає Grok Imagine для генерації зображень і відео. Доступ залежить від того, який рівень The X Subscription ви маєте, від Free до Ultra."}]$x$::jsonb
