UPDATE tools SET faq = $x$[{"q": "Wofür wird Character.AI verwendet?", "a": "Character.AI wird für konversationelles Rollenspiel mit KI-Personas genutzt. Nutzer chatten mit KI-Versionen von Prominenten, fiktiven Charakteren, historischen Persönlichkeiten oder eigenen Bots. Es dient vor allem der Unterhaltung, sozialen Interaktion und kreativem Schreiben — nicht für Arbeitsaufgaben."}, {"q": "Ist Character.AI sicher?", "a": "Character.AI schließt Nutzer unter 18 Jahren seit 2025 infolge von Sicherheitsbedenken von offenen Chats und Rollenspielen aus und verwendet eigene unternehmensinterne Altersschätzungstools zur Altersprüfung. Eltern können über Parental Insights eine wöchentliche Zusammenfassung der Aktivitäten ihres Teenagers erhalten. Trotz dieser Maßnahmen stand die Plattform wegen früherer unangemessener Gespräche mit Minderjährigen in der Kritik, daher sollten Eltern die Nutzung weiterhin überwachen."}, {"q": "Kann Character.AI bei Hausaufgaben helfen?", "a": "Character.AI kann Bildungsgespräche führen, priorisiert dabei aber häufig das Verbleiben in der Charakterrolle gegenüber sachlicher Richtigkeit. Für Hausaufgabenhilfe sind ChatGPT, Claude oder Khanmigo deutlich zuverlässiger und genauer."}, {"q": "Ist ChatGPT besser als Character.AI?", "a": "Für Arbeit, Recherche und reale Aufgaben – ja, ChatGPT ist weitaus leistungsfähiger. Für Unterhaltung, Rollenspiel und charakterbasierte Gespräche ist Character.AI speziell dafür konzipiert und verfügt über eine größere Charakter-Community. Beide decken völlig unterschiedliche Einsatzzwecke ab."}]$x$::jsonb
