UPDATE tools SET faq = $x$[{"q": "Для чего используется Character.AI?", "a": "Character.AI используется для ролевого общения с ИИ-персонами. Пользователи общаются с ИИ-версиями знаменитостей, вымышленных персонажей, исторических личностей или кастомных ботов. Это в первую очередь предназначено для развлечения, социального взаимодействия и творческого письма — не для рабочих задач."}, {"q": "Безопасен ли Character.AI?", "a": "С 2025 года Character.AI ограничивает пользователям младше 18 лет доступ к свободному общению и ролевым играм из-за соображений безопасности и использует собственные внутренние инструменты оценки возраста. Родители могут получать еженедельную сводку активности подростка через Parental Insights. Несмотря на эти меры, платформа подвергалась критике за прошлые случаи неподобающих разговоров с несовершеннолетними, поэтому родителям всё же стоит следить за использованием."}, {"q": "Может ли Character.AI помочь с домашним заданием?", "a": "Character.AI способен вести образовательные беседы, но часто отдаёт приоритет сохранению образа персонажа, а не фактической точности. Для помощи с домашними заданиями ChatGPT, Claude или Khanmigo значительно более надёжны и точны."}, {"q": "Лучше ли ChatGPT, чем Character.AI?", "a": "Для работы, исследований и реальных задач — да, ChatGPT гораздо более функционален. Для развлечений, ролевых игр и общения с персонажами Character.AI создан именно для этого и имеет более крупное сообщество персонажей. Это совершенно разные сценарии использования."}]$x$::jsonb
