UPDATE tools SET description = $x$Character.AI היא פלטפורמה לצ'אט עם דמויות AI שנוצרו על ידי משתמשים, אך נכון לאוקטובר 2026 היא פועלת תחת הגנת פשיטת רגל מסוג Chapter 11 בעוד היא מחפשת קונה לנכסיה.$x$
 WHERE slug = 'character-ai' AND lang = 'he';

UPDATE tools SET description_long = $x$Character.AI היא פלטפורמת צ'אט המבוססת על פרסונות AI: אתם משוחחים עם אלפי דמויות שנוצרו על ידי משתמשים, החל מדמויות בדיוניות ועד עוזרים ובני לוויה, או בונים דמות משלכם. זו הייתה במשך זמן רב אחת מאפליקציות הצ'אט הצרכניות הנפוצות ביותר מחוץ לעוזרים הכלליים הגדולים.

נכון לסוף ספטמבר 2026, סגנון הצ'אט ברירת המחדל של הפלטפורמה היה PipSqueak 3, כאשר ShortSqueak זמין במסלול החינמי ו-DeepSqueak ו-LongSqueak שמורים למסלולים בתשלום. ב-12 באוקטובר 2026, החברה הגישה בקשה לפשיטת רגל מסוג Chapter 11 בדלאוור לצורך מכירת נכסיה; Disney הגישה הצעה ראשונית בסך 20 מיליון דולר עבור רישיון לא בלעדי לחלק מהטכנולוגיה שלה, והמכירה צפויה להיסגר עד סוף נובמבר או תחילת דצמבר 2026.

היכולות המרכזיות כוללות משחק תפקידים וסיפור סיפורים בשיחה רב-תורית, יצירת דמויות מותאמות אישית עם פרסונות וקולות, שיחות קוליות, וכלים ליצירת סרטונים, סיפורים ושידורים.

התמחור הוא freemium. המסלול החינמי מציע שליחת הודעות ללא הגבלה ב-PipSqueak 3 וב-ShortSqueak אך מציג פרסומות. מסלול (c.ai) lite עולה 4.99 דולר לחודש או 2.49 דולר לשבוע (המחיר עשוי להשתנות לפי אזור) ומוסיף מכסה יומית של הודעות פרימיום ב-DeepSqueak וב-LongSqueak, פחות פרסומות, מצב האטה פחות מגביל, התאמה אישית נוספת ונעיצות זיכרון נוספות. מסלול c.ai+ גבוה יותר מבטיח שיחות פרימיום ללא הגבלה, אפס פרסומות ותכונות זיכרון מלאות, אך מחירו לא ניתן לאימות במקור ראשי. מדווח כי גם המנויים בתשלום וגם המסלול החינמי נותרים פעילים במהלך תהליך פשיטת הרגל.

חלות מגבלות משמעותיות. מאז 25 בנובמבר 2025, משתמשים מתחת לגיל 18 אינם יכולים עוד לנהל צ'אט פתוח או משחק תפקידים והם מופנים ליצירת סרטונים, סיפורים ושידורים, כאשר אימות הגיל מתבצע באמצעות כלי הערכת גיל פנימיים של החברה עצמה. באופן דחוף יותר, הפלטפורמה נמצאת כעת תחת פשיטת רגל מסוג Chapter 11 ועלולה להיסגר לחלוטין אם לא יימצא קונה בר-קיימא בתהליך המכירה; מומלץ למשתמשים לייצא את נתוני הצ'אט שלהם בעודה הפלטפורמה פעילה.

היא מתאימה למבוגרים המעוניינים בצ'אט ומשחק תפקידים מבוססי דמויות, וליוצרים הבונים פרסונות וסיפורים אינטראקטיביים, אך משתמשים פוטנציאליים צריכים להיות מודעים לכך שהישרדותה ארוכת הטווח של הפלטפורמה אינה ודאית בעוד תהליך המכירה בפשיטת הרגל מתנהל. קטינים ומשתמשים המעוניינים בחוויה חינמית ללא הגבלות צריכים לחפש פתרון אחר.$x$
 WHERE slug = 'character-ai' AND lang = 'he';

