UPDATE tools SET faq = $x$[{"q": "À quoi sert Character.AI ?", "a": "Character.AI sert au jeu de rôle conversationnel avec des personas IA. Les utilisateurs discutent avec des versions IA de célébrités, de personnages fictifs, de figures historiques ou de bots personnalisés. C'est principalement destiné au divertissement, à l'interaction sociale et à l'écriture créative, et non aux tâches professionnelles."}, {"q": "Character.AI est-il sûr ?", "a": "Character.AI interdit aux utilisateurs de moins de 18 ans le chat et le jeu de rôle ouvert depuis 2025, suite à des préoccupations de sécurité, et utilise ses propres outils internes d'estimation d'âge pour la vérification de l'âge. Les parents peuvent obtenir un résumé hebdomadaire de l'activité de leur adolescent via Parental Insights. Malgré ces mesures, la plateforme a fait l'objet d'un examen minutieux concernant des conversations inappropriées passées avec des mineurs, les parents devraient donc tout de même surveiller son utilisation."}, {"q": "Character.AI peut-il aider pour les devoirs ?", "a": "Character.AI peut avoir des conversations éducatives, mais privilégie souvent le maintien du personnage au détriment de l'exactitude factuelle. Pour l'aide aux devoirs, ChatGPT, Claude ou Khanmigo sont nettement plus fiables et précis."}, {"q": "ChatGPT est-il meilleur que Character.AI ?", "a": "Pour le travail, la recherche et les tâches réelles, oui, ChatGPT est bien plus performant. Pour le divertissement, le jeu de rôle et les conversations basées sur des personnages, Character.AI est conçu spécifiquement pour cela et dispose d'une communauté de personnages plus large. Ils répondent à des usages complètement différents."}]$x$::jsonb
 WHERE slug = 'character-ai' AND lang = 'fr';

