UPDATE tools SET faq = $x$[{"q": "Para que o Character.AI é usado?", "a": "Character.AI é usado para roleplay conversacional com personas de IA. Os usuários conversam com versões de IA de celebridades, personagens fictícios, figuras históricas ou bots personalizados. É principalmente para entretenimento, interação social e escrita criativa — não para tarefas de trabalho."}, {"q": "O Character.AI é seguro?", "a": "O Character.AI restringe usuários menores de 18 anos de fazer chat aberto e roleplay desde 2025, após preocupações com segurança, e usa suas próprias ferramentas internas de estimativa de idade para verificação. Os pais podem receber um resumo semanal da atividade do adolescente por meio do Parental Insights. Apesar dessas medidas, a plataforma já enfrentou escrutínio por conversas inadequadas anteriores com menores, então os pais ainda devem monitorar o uso."}, {"q": "O Character.AI pode ajudar com tarefas escolares?", "a": "O Character.AI pode ter conversas educacionais, mas frequentemente prioriza manter o personagem em vez da precisão factual. Para ajuda com tarefas escolares, ChatGPT, Claude ou Khanmigo são significativamente mais confiáveis e precisos."}, {"q": "O ChatGPT é melhor que o Character.AI?", "a": "Para trabalho, pesquisa e tarefas reais — sim, o ChatGPT é muito mais capaz. Para entretenimento, roleplay e conversas baseadas em personagens, o Character.AI foi criado especificamente para isso e tem uma comunidade de personagens maior. Eles atendem a casos de uso completamente diferentes."}]$x$::jsonb
 WHERE slug = 'character-ai' AND lang = 'pt';

