UPDATE tools SET faq = $x$[{"q": "Що таке Notion AI?", "a": "Notion AI — це AI-асистент, вбудований безпосередньо в Notion. Він може писати, підсумовувати, перекладати та відповідати на питання, використовуючи вміст вашого робочого простору як контекст."}, {"q": "Скільки коштує Notion AI?", "a": "Notion AI не є окремим доповненням. Плани Free та Plus включають лише обмежену пробну версію Notion AI. Повний, постійний AI включений у план Business ($20 за місце на місяць за річної оплати, близько $24 за місце на місяць за помісячної оплати) та в Enterprise, який має індивідуальну ціну."}, {"q": "Що таке Skills у Notion 3.7?", "a": "Notion 3.7 (вересень 2026) запровадив Skills для агентів та бібліотеку skills, з можливістю експортувати Skills у зовнішні інструменти, такі як Claude Code, Codex, Cursor, Gemini і Grok, а також Custom Agents, здатні викликати субагентів."}, {"q": "Як працюють кредити Custom Agent?", "a": "Custom Agents безкоштовні для пробного використання, а потім коштують $10 за 1000 щомісячних кредитів Notion, що тарифікується понад вашу звичайну ціну місця."}]$x$::jsonb
