UPDATE tools SET faq = $x$[{"q": "Qu'est-ce que Notion AI ?", "a": "Notion AI est un assistant IA intégré directement à Notion. Il peut rédiger, résumer, traduire et répondre à des questions en utilisant le contenu de votre espace de travail comme contexte."}, {"q": "Combien coûte Notion AI ?", "a": "Notion AI n'est pas un module séparé. Les forfaits Free et Plus n'incluent qu'un essai plafonné de Notion AI. L'IA complète et continue est incluse dans le forfait Business (20 $ par poste et par mois facturé annuellement, environ 24 $ par poste et par mois facturé mensuellement) et dans Enterprise, dont le tarif est personnalisé."}, {"q": "Que sont les Skills dans Notion 3.7 ?", "a": "Notion 3.7 (septembre 2026) a introduit les Skills pour agents et une bibliothèque de skills, avec la possibilité d'exporter des Skills vers des outils externes tels que Claude Code, Codex, Cursor, Gemini et Grok, ainsi que des Custom Agents capables d'appeler des sous-agents."}, {"q": "Comment fonctionnent les crédits Custom Agent ?", "a": "Les Custom Agents sont gratuits à l'essai, puis coûtent 10 $ pour 1 000 crédits Notion mensuels, facturés en plus de votre prix de poste habituel."}]$x$::jsonb
