UPDATE tools SET faq = $x$[{"a": "Microsoft Copilot es el asistente de IA de Microsoft integrado en Windows, Microsoft 365 (Word, Excel, Outlook, Teams), Edge y Bing. Utiliza por defecto los modelos de OpenAI, con los modelos de Anthropic también disponibles en las experiencias licenciadas aplicables, para ayudar con tareas en todo el ecosistema de Microsoft.", "q": "¿Qué es Microsoft Copilot?"}, {"a": "La licencia de Copilot se divide en niveles: Copilot Chat (Basic), Microsoft 365 Copilot (Basic) para acceso dentro de la aplicación a Word, Excel, PowerPoint y OneNote, un complemento Microsoft 365 Copilot (Premium), y el nuevo Copilot Cowork basado en uso. Los precios actuales en dólares para estos niveles no pudieron verificarse en las páginas de precios de Microsoft al momento de escribir esto.", "q": "¿Cuánto cuesta Microsoft Copilot?"}, {"a": "Copilot en Excel puede generar fórmulas, crear tablas dinámicas, resumir datos, crear gráficos y responder preguntas sobre tu hoja de cálculo en lenguaje natural.", "q": "¿Qué puede hacer Microsoft Copilot en Excel?"}, {"a": "No. Microsoft Copilot es un asistente de IA de propósito general para Windows y las aplicaciones de M365. GitHub Copilot es un producto distinto centrado en la finalización de código y el desarrollo, disponible en github.com/features/copilot.", "q": "¿Es Microsoft Copilot lo mismo que GitHub Copilot?"}]$x$::jsonb
